var smallestIndex = function(nums) {
    function digitSum(x) {
        let s = 0;
        while (x > 0) {
            s += x % 10;
            x = Math.floor(x / 10);
        }
        return s;
    }

    for (let i = 0; i < nums.length; ++i) {
        if (digitSum(nums[i]) === i) {
            return i;
        }
    }
    return -1;
};
